import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, positionLocal, color, mix, smoothstep, vec3, float, min } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight } = ctx.THREE;

  const root = new Group();
  const geometries = [];
  const materials = [];
  const timelines = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ACCENT = colors.accent ?? '#ff2a38';
  const PAPER = colors.paper ?? '#e8ecf2';
  const GRAD0 = (colors.gradientStops && colors.gradientStops[0]?.hex) || '#101017';
  const GRAD1 = (colors.gradientStops && colors.gradientStops[1]?.hex) || '#1a1a22';

  // ---------- text content (verbatim from spec) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRoleQueue = {};
  for (const it of items) {
    const role = it.role || 'label';
    (byRoleQueue[role] = byRoleQueue[role] || []).push(it);
  }
  const take = (role, fallback) => {
    const q = byRoleQueue[role];
    if (q && q.length) return q.shift().text;
    return fallback;
  };
  const captionCopy = take('caption', 'ATELIER METRICS / Q2 2026');
  const heroValue = take('valueLarge', '0.002 mm');
  const heroLabel = take('label', 'Case tolerance, CNC pass');
  const v1 = take('value', '38 h');
  const l1 = take('label', 'Power reserve, NA-01');
  const v2 = take('value', '214');
  const l2 = take('label', 'Components per calibre');

  // ---------- backdrop stage (7x6 @ z=-2.5, engineered vertical gradient) ----------
  const bgGeo = new PlaneGeometry(7, 6);
  geometries.push(bgGeo);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(color(GRAD1), color(GRAD0), uv().y);
  materials.push(bgMat);
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // subtle mid-plane shadow card behind the grid for depth separation
  const shadowGeo = new PlaneGeometry(6.0, 4.0);
  geometries.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial();
  const sd = uv().sub(0.5).length().mul(2.0);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(1.0, 0.35, sd).mul(0.5);
  shadowMat.transparent = true;
  materials.push(shadowMat);
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.1, -0.6);
  root.add(shadowPlane);

  // ---------- node-local rim light (accent hue, opposite key) ----------
  const rim = new DirectionalLight(ACCENT, 0.8);
  rim.position.set(-4, 1.5, -3);
  root.add(rim);
  root.add(rim.target);

  // ---------- machined slab material factory ----------
  function makeCellMaterial(w, h) {
    const px = positionLocal.x.div(w).add(0.5);
    const py = positionLocal.y.div(h).add(0.5);
    // 135-deg diagonal: top-left -> bottom-right
    const diag = px.add(py.oneMinus()).mul(0.5);
    const base = mix(color(GRAD0), color(GRAD1), diag);
    // hard-stop machined sheen band, 0.15 units wide at 40%, +6% value
    const bw = 0.15 / ((w + h) * 0.5);
    const lo = 0.4 - bw * 0.5;
    const hi = 0.4 + bw * 0.5;
    const band = smoothstep(float(lo - 0.008), float(lo), diag)
      .mul(smoothstep(float(hi + 0.008), float(hi), diag));
    // chamfer highlight catching the key light along edges
    const dx = min(px, px.oneMinus()).mul(w);
    const dy = min(py, py.oneMinus()).mul(h);
    const edge = smoothstep(float(0.05), float(0.0), min(dx, dy));
    const col = base
      .add(vec3(band.mul(0.06)))
      .add(vec3(edge.mul(0.085), edge.mul(0.088), edge.mul(0.1)));
    const mat = new MeshStandardNodeMaterial({
      roughness: 0.5,
      metalness: 0.45,
      transparent: true,
      opacity: 0,
    });
    mat.colorNode = col;
    materials.push(mat);
    return mat;
  }

  function makeTickBar() {
    const g = new BoxGeometry(0.4, 0.05, 0.02);
    geometries.push(g);
    const m = new MeshStandardNodeMaterial({
      color: ACCENT,
      emissive: ACCENT,
      emissiveIntensity: 1.3,
      roughness: 0.6,
      metalness: 0.2,
    });
    materials.push(m);
    return new Mesh(g, m);
  }

  // ---------- grid geometry: 5.5 x 3.5, gutter 0.25 ----------
  const DEPTH = 0.06;
  const FRONT = DEPTH / 2 + 0.001;

  const cellDefs = [
    { w: 3.25, h: 3.5, cx: -1.125, cy: 0, dominant: true },
    { w: 2.0, h: 1.625, cx: 1.75, cy: 0.9375, dominant: false },
    { w: 2.0, h: 1.625, cx: 1.75, cy: -0.9375, dominant: false },
  ];

  const cellGroups = [];
  const cellMats = [];

  const heroTexts = [
    { value: heroValue, label: heroLabel },
    { value: v1, label: l1 },
    { value: v2, label: l2 },
  ];

  cellDefs.forEach((def, i) => {
    const grp = new Group();
    grp.position.set(def.cx, def.cy, 0);

    const slabGeo = new BoxGeometry(def.w, def.h, DEPTH);
    geometries.push(slabGeo);
    const slabMat = makeCellMaterial(def.w, def.h);
    cellMats.push(slabMat);
    const slab = new Mesh(slabGeo, slabMat);
    grp.add(slab);

    const pad = def.dominant ? 0.5 : 0.3;
    const left = -def.w / 2 + pad;
    const top = def.h / 2 - pad;

    // accent tick bar, top-left inside padding
    const tick = makeTickBar();
    tick.position.set(left + 0.2, top - 0.025, FRONT + 0.01);
    grp.add(tick);

    const t = heroTexts[i];
    if (def.dominant) {
      const valueText = ctx.fontAtlas.createText(String(t.value), {
        fontSize: 124,
        color: PAPER,
        align: 'left',
        letterSpacingPx: -1,
      });
      valueText.position.set(left, top - 1.05, FRONT + 0.02);
      grp.add(valueText);

      const labelText = ctx.fontAtlas.createText(String(t.label).toUpperCase(), {
        fontSize: 18,
        color: '#9aa2ad',
        align: 'left',
        letterSpacingPx: 1.5,
      });
      labelText.position.set(left, top - 1.55, FRONT + 0.02);
      grp.add(labelText);
    } else {
      const valueText = ctx.fontAtlas.createText(String(t.value), {
        fontSize: 68,
        color: PAPER,
        align: 'left',
      });
      valueText.position.set(left, top - 0.55, FRONT + 0.02);
      grp.add(valueText);

      const labelText = ctx.fontAtlas.createText(String(t.label).toUpperCase(), {
        fontSize: 18,
        color: '#9aa2ad',
        align: 'left',
        letterSpacingPx: 1.5,
      });
      labelText.position.set(left, top - 0.95, FRONT + 0.02);
      grp.add(labelText);
    }

    cellGroups.push(grp);
    root.add(grp);
  });

  // ---------- header caption above grid, left-aligned to grid edge ----------
  const header = ctx.fontAtlas.createText(String(captionCopy), {
    fontSize: 18,
    color: ACCENT,
    align: 'left',
    letterSpacingPx: 2,
  });
  header.position.set(-2.75, 2.25, 0.05);
  root.add(header);

  // ---------- entrance: stagger-cards / fade-up, dominant first ----------
  const entrance = gsap.timeline();
  timelines.push(entrance);
  cellDefs.forEach((def, i) => {
    const at = i * 0.08;
    entrance.fromTo(
      cellGroups[i].position,
      { y: def.cy + 0.2 },
      { y: def.cy, duration: 0.5, ease: 'power2.out' },
      at
    );
    entrance.fromTo(
      cellMats[i],
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: 'power2.out' },
      at
    );
  });
  // weighted settle on the whole grid
  entrance.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.1
  );

  // ---------- hover: press-down / weighted-settle release ----------
  root.userData.handlers = {
    pointerenter: () => {
      gsap.killTweensOf(root.scale);
      gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
    },
    pointerleave: () => {
      gsap.killTweensOf(root.scale);
      const tl = gsap.timeline();
      timelines.push(tl);
      tl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.12, ease: 'power2.out' })
        .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    },
    click: () => {
      gsap.killTweensOf(root.scale);
      const tl = gsap.timeline();
      timelines.push(tl);
      tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
        .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    },
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf(root.scale);
    cellGroups.forEach((g) => gsap.killTweensOf(g.position));
    cellMats.forEach((m) => gsap.killTweensOf(m));
    geometries.forEach((g) => g.dispose());
    materials.forEach((m) => m.dispose());
    root.traverse((obj) => {
      if (obj.geometry && !geometries.includes(obj.geometry)) obj.geometry.dispose();
      if (obj.material && !materials.includes(obj.material)) {
        if (Array.isArray(obj.material)) obj.material.forEach((mm) => mm.dispose());
        else obj.material.dispose();
      }
    });
  };

  return root;
}
